package br.com.sussmartcare.telemetry.adapters.in.rest; import br.com.sussmartcare.telemetry.application.*; import br.com.sussmartcare.telemetry.domain.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/v1") public class TelemetryController { private final TelemetryApplicationService app; private final TelemetrySummaryService summaries; public TelemetryController(TelemetryApplicationService a,TelemetrySummaryService s){app=a;summaries=s;} public record DeviceRequest(@NotBlank String externalId,@NotBlank String deviceType,String manufacturer,String model){} public record SessionRequest(@NotNull UUID patientId,UUID visitId,UUID preHospitalEncounterId,@NotBlank String sourceContext){} public record ObservationRequest(@NotNull UUID deviceId,@NotBlank String type,@NotNull Double value,String unit,Instant measuredAt){} @PostMapping("/devices") public ResponseEntity<MedicalDevice> device(@Valid @RequestBody DeviceRequest r){return ResponseEntity.status(201).body(app.register(r.externalId(),r.deviceType(),r.manufacturer(),r.model()));} @PostMapping("/telemetry/sessions") public ResponseEntity<TelemetrySession> session(@Valid @RequestBody SessionRequest r){return ResponseEntity.status(201).body(app.start(r.patientId(),r.visitId(),r.preHospitalEncounterId(),r.sourceContext()));} @PostMapping("/telemetry/sessions/{id}/observations") public ResponseEntity<BiometricObservation> observation(@PathVariable UUID id,@Valid @RequestBody ObservationRequest r){return ResponseEntity.status(202).body(app.ingest(id,r.deviceId(),r.type(),r.value(),r.unit(),r.measuredAt()));}  @GetMapping("/telemetry/sessions/{sessionId}/summary") public TelemetrySummaryService.Summary summary(@PathVariable UUID sessionId,@RequestParam String type){return summaries.summarize(sessionId,type.trim().toUpperCase().replace(' ','_'));} }
